-- Adds the invoice generator to an EXISTING safety_store database (safe to run more than once):
-- psql -U postgres -d safety_store -f migrate_invoices.sql
-- New installs do not need this file: schema.sql already includes it.
SET client_encoding='UTF8';
-- Invoices: status is draft/sent/void; paid, partial and overdue are worked out from the payments and the due date.
CREATE SEQUENCE IF NOT EXISTS invoice_seq;
CREATE TABLE IF NOT EXISTS recurring_invoices(id SERIAL PRIMARY KEY,customer_name TEXT NOT NULL,customer_email TEXT NOT NULL DEFAULT '',customer_phone TEXT NOT NULL DEFAULT '',customer_address TEXT NOT NULL DEFAULT '',items JSONB NOT NULL,tax_rate NUMERIC(5,2) NOT NULL DEFAULT 0,discount NUMERIC(10,2) NOT NULL DEFAULT 0,notes TEXT NOT NULL DEFAULT '',frequency TEXT NOT NULL CHECK(frequency IN('weekly','monthly','quarterly','yearly')),due_days INT NOT NULL DEFAULT 14,start_date DATE NOT NULL,runs INT NOT NULL DEFAULT 1,next_date DATE NOT NULL,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices(id SERIAL PRIMARY KEY,number TEXT NOT NULL UNIQUE,token TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','sent','void')),customer_name TEXT NOT NULL,customer_email TEXT NOT NULL DEFAULT '',customer_phone TEXT NOT NULL DEFAULT '',customer_address TEXT NOT NULL DEFAULT '',order_id INT REFERENCES orders(id) ON DELETE SET NULL,recurring_id INT REFERENCES recurring_invoices(id) ON DELETE SET NULL,issue_date DATE NOT NULL,due_date DATE NOT NULL,tax_rate NUMERIC(5,2) NOT NULL DEFAULT 0,discount NUMERIC(12,2) NOT NULL DEFAULT 0,subtotal NUMERIC(12,2) NOT NULL,tax NUMERIC(12,2) NOT NULL,total NUMERIC(12,2) NOT NULL,notes TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS invoices_status_idx ON invoices(status,due_date);
CREATE TABLE IF NOT EXISTS invoice_items(id SERIAL PRIMARY KEY,invoice_id INT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,product_id INT REFERENCES products(id) ON DELETE SET NULL,description TEXT NOT NULL,qty NUMERIC(10,2) NOT NULL CHECK(qty>0),unit_price NUMERIC(10,2) NOT NULL CHECK(unit_price>=0),position INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS invoice_payments(id SERIAL PRIMARY KEY,invoice_id INT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,amount NUMERIC(12,2) NOT NULL CHECK(amount>0),method TEXT NOT NULL,paid_on DATE NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS invoice_payments_inv_idx ON invoice_payments(invoice_id);
